        "<table><thead><tr><th>参数</th><th>说明</th><th>类型</th><th>可选值</th><th>默认值</th></tr></thead><tbody><tr><td>方法名</td><td>详情</td><td>Type</td><td></td><td></td></tr><tr><td>popperRef</td><td>b-popper 组件实例</td><td>^[object]`Ref&lt;PopperInstance \\| undefined&gt;`</td><td></td><td></td></tr><tr><td>contentRef</td><td>b-tooltip-content 组件实例</td><td>^[object]`Ref&lt;TooltipContentInstance \\| undefined&gt;`</td><td></td><td></td></tr><tr><td>isFocusInsideContent</td><td>验证当前焦点事件是否在 b-tooltip-content 中触发</td><td>^[Function]`() =&gt; boolean \\| undefined`</td><td></td><td></td></tr><tr><td>updatePopper</td><td>更新 b-popper组件实例</td><td>^[Function]`() =&gt; void`</td><td></td><td></td></tr><tr><td>onOpen</td><td>onClose 方法控制 b-tooltip 显示状态</td><td>^[Function]`(event?: Event \\| undefined) =&gt; void`</td><td></td><td></td></tr><tr><td>onClose</td><td>onClose 方法控制 b-tooltip 显示状态</td><td>^[Function]`(event?: Event \\| undefined) =&gt; void`</td><td></td><td></td></tr><tr><td>hide</td><td>提供 hide 方法</td><td>^[Function]`(event?: Event \\| undefined) =&gt; void`</td><td></td><td></td></tr></tbody></table>";
